def calculer_taux_gc(brin: str) -> float:
    compte_gc = 0
    for base in brin:
        if base == 'G' or base == 'C':
            compte_gc = compte_gc + 1
    return compte_gc / len(brin)

def est_riche_en_gc(brin: str) -> bool:
    taux = calculer_taux_gc(brin)
    return taux >= 0.5

sequences = ["ATGC", "GGCC", "AAAA", "GCGC"]
compteur = 0
for seq in sequences:
    if est_riche_en_gc(seq):
        compteur = compteur + 1
print(compteur)
